begin;
create schema test_jobs;
create table test_jobs.assertions(label text primary key);
create table test_jobs.results(label text primary key,value jsonb);
create function test_jobs.ok(condition boolean,label text) returns void language plpgsql as $$
begin
  if condition is not true then raise exception 'Assertion failed: %',label; end if;
  insert into test_jobs.assertions values(label);
end;
$$;
create function test_jobs.raises(query text,expected_state text,label text) returns void language plpgsql as $$
begin
  begin execute query;
  exception when others then
    if sqlstate=expected_state then insert into test_jobs.assertions values(label); return; end if;
    raise;
  end;
  raise exception 'Expected SQLSTATE %: %',expected_state,label;
end;
$$;
grant usage on schema test_jobs to anon,authenticated,service_role;
grant all on all tables in schema test_jobs to anon,authenticated,service_role;
grant execute on all functions in schema test_jobs to anon,authenticated,service_role;
insert into auth.users(id,email,email_confirmed_at) values('11000000-0000-4000-8000-000000000001','jobs@example.test',now());
insert into auth.sessions(id,user_id) values('22000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000001');
insert into private.session_verifications(session_id,user_id,state,verified_at) values('22000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000001','verified',now());
insert into public.projects(id,owner_id,name) values('33000000-0000-4000-8000-000000000001','11000000-0000-4000-8000-000000000001','Job callbacks fixture');
update public.video_credit_accounts set credits=1000 where user_id='11000000-0000-4000-8000-000000000001';
select test_jobs.ok((select count(*)=3 and bool_and(c.relrowsecurity and c.relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='private' and c.relname in ('job_dispatch_outbox','provider_job_bindings','provider_callback_events')),'all new tables force RLS');
set role service_role;
select public.configure_generation_policy(true,'USD',10000,10000,10,'UTC');
select public.configure_generation_account('11000000-0000-4000-8000-000000000001',true);
select public.upsert_generation_price('jobs.fixture',10,100,'{"provider":"fixture","model":"bounded"}',true);
insert into test_jobs.results values('first',public.reserve_generation_for_user('11000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','jobs-request-key-0001','jobs.fixture','Stored prompt','Fixture'));
select test_jobs.ok(jsonb_array_length(public.generation_dispatch_batch(100))=1,'reservation atomically creates outbox');
select test_jobs.ok(public.generation_dispatch_batch(100)->0->>'provider'='fixture','batch provider comes from stored profile');
select test_jobs.ok(not (public.generation_dispatch_batch(100)->0 ? 'prompt') and not (public.generation_dispatch_batch(100)->0 ? 'profile'),'outbox event has no prompt or provider profile');
select test_jobs.ok(public.generation_job_context('00000000-0000-0000-0000-000000000000') is null,'unknown request context is null');
select test_jobs.raises($q$select public.generation_dispatch_batch(101)$q$,'22023','dispatch batch bounded');
select test_jobs.raises($q$select public.generation_reconciliation_batch(0)$q$,'22023','reconciliation batch bounded');
select test_jobs.raises($q$select public.apply_generation_callback('fixture','unknown-event','unknown-job','succeeded',50,repeat('a',64))$q$,'P0002','unknown provider job rejected');
reset role;
select test_jobs.ok((select count(*)=0 from private.provider_callback_events),'unknown callback does not write inbox');
select test_jobs.ok((select status='reserved' from private.generation_reservations),'unknown callback does not change status');
select test_jobs.ok((select credits=990 from public.video_credit_accounts where user_id='11000000-0000-4000-8000-000000000001'),'unknown callback cannot alter credits');
set role service_role;
select test_jobs.ok((public.claim_generation('11000000-0000-4000-8000-000000000001','jobs-request-key-0001')->>'dispatchAllowed')::boolean,'first execution claims once');
select test_jobs.ok(not (public.claim_generation('11000000-0000-4000-8000-000000000001','jobs-request-key-0001')->>'dispatchAllowed')::boolean,'retried execution cannot claim again');
select public.mark_generation_unknown('11000000-0000-4000-8000-000000000001','jobs-request-key-0001');
select test_jobs.ok(jsonb_array_length(public.generation_reconciliation_batch(100))=1,'ambiguous jobs enter read-only reconciliation batch');
select test_jobs.raises($q$select public.apply_generation_callback('fixture','early-event','fixture-job-1','succeeded',50,repeat('b',64))$q$,'P0002','callback before authoritative binding rejected without guessing');
select test_jobs.raises($q$select public.generation_bind_reconciled_job((select (value->>'requestId')::uuid from test_jobs.results where label='first'),'other','fixture-job-1')$q$,'23505','reconciliation cannot change persisted provider');
select test_jobs.ok(public.generation_bind_reconciled_job((select (value->>'requestId')::uuid from test_jobs.results where label='first'),'fixture','fixture-job-1')->>'providerJobId'='fixture-job-1','read-only provider recovery binds accepted job');
select test_jobs.raises($q$select public.mark_generation_dispatched('11000000-0000-4000-8000-000000000001','jobs-request-key-0001','different-job')$q$,'23505','provider binding cannot change');
select test_jobs.ok((public.apply_generation_callback('fixture','progress-1','fixture-job-1','running',null,repeat('c',64))->>'applied')::boolean=false,'progress has no financial transition');
insert into test_jobs.results values('settle',public.apply_generation_callback('fixture','terminal-1','fixture-job-1','succeeded',60,repeat('d',64)));
select test_jobs.ok((select (value->>'applied')::boolean and value->>'status'='committed' from test_jobs.results where label='settle'),'terminal callback settles atomically');
select test_jobs.ok((public.apply_generation_callback('fixture','terminal-1','fixture-job-1','succeeded',60,repeat('d',64))->>'duplicate')::boolean,'duplicate event recognized');
select test_jobs.ok(not (public.apply_generation_callback('fixture','terminal-2','fixture-job-1','succeeded',60,repeat('e',64))->>'applied')::boolean,'another terminal event cannot settle twice');
select test_jobs.ok(not (public.apply_generation_callback('fixture','late-progress','fixture-job-1','running',null,repeat('f',64))->>'applied')::boolean,'late progress ignored');
select test_jobs.ok(not (public.apply_generation_callback('fixture','conflicting-terminal','fixture-job-1','failed',90,repeat('a',64))->>'applied')::boolean,'conflicting late terminal ignored');
select test_jobs.raises($q$select public.apply_generation_callback('fixture','terminal-1','fixture-job-1','succeeded',60,repeat('b',64))$q$,'23505','same event changed payload rejected');
select test_jobs.raises($q$select public.apply_generation_callback('other','terminal-1','fixture-job-1','succeeded',60,repeat('d',64))$q$,'P0002','different provider cannot target binding');
select test_jobs.ok(public.generation_dispatch_sent((select (value->>'requestId')::uuid from test_jobs.results where label='first')),'delivery ack succeeds');
select test_jobs.ok(public.generation_dispatch_sent((select (value->>'requestId')::uuid from test_jobs.results where label='first')),'delivery ack retry idempotent');
select test_jobs.ok(jsonb_array_length(public.generation_dispatch_batch(100))=0,'acked delivery leaves batch');
reset role;
update private.job_dispatch_outbox set delivered_at=clock_timestamp()-interval '6 minutes';
set role service_role;
select test_jobs.ok(jsonb_array_length(public.generation_dispatch_batch(100))=0,'terminal jobs never redrive after delivery');
reset role;
select test_jobs.ok((select committed_micros=60 and reserved_micros=0 from private.generation_global_days),'duplicate and out-of-order callbacks settle ledger once');
select test_jobs.ok((select active_jobs=0 from private.generation_active_jobs),'settlement frees exactly one active slot');
select test_jobs.ok((select status='succeeded' and owner_id='11000000-0000-4000-8000-000000000001' and project_id='33000000-0000-4000-8000-000000000001' from public.jobs),'callbacks preserve owner and project');
select test_jobs.ok((select credits=990 from public.video_credit_accounts where user_id='11000000-0000-4000-8000-000000000001'),'settlement does not debit credits again');
set role service_role;
insert into test_jobs.results values('second',public.reserve_generation_for_user('11000000-0000-4000-8000-000000000001','22000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','jobs-request-key-0002','jobs.fixture','Stored prompt','Fixture'));
select public.generation_dispatch_sent((select (value->>'requestId')::uuid from test_jobs.results where label='second'));
reset role;
update private.job_dispatch_outbox set delivered_at=clock_timestamp()-interval '6 minutes' where request_id=(select (value->>'requestId')::uuid from test_jobs.results where label='second');
set role service_role;
select test_jobs.ok(jsonb_array_length(public.generation_dispatch_batch(100))=1,'accepted event with exhausted worker retries redrives reserved job');
select public.claim_generation('11000000-0000-4000-8000-000000000001','jobs-request-key-0002');
select test_jobs.ok(jsonb_array_length(public.generation_dispatch_batch(100))=1,'stale claimed job redrives reconciliation without fresh paid claim');

select test_jobs.raises($q$select public.mark_generation_dispatched('11000000-0000-4000-8000-000000000001','jobs-request-key-0002','fixture-job-1')$q$,'23505','one paid provider job cannot belong to two reservations');
select public.mark_generation_dispatched('11000000-0000-4000-8000-000000000001','jobs-request-key-0002','fixture-job-2');
select test_jobs.raises($q$select public.apply_generation_callback('fixture','terminal-1','fixture-job-2','succeeded',60,repeat('d',64))$q$,'23505','same provider event cannot target another project job');
select test_jobs.ok(public.apply_generation_callback('fixture','overage','fixture-job-2','succeeded',120,repeat('1',64))->>'status'='reconciliation_required','overage retained for operator');
select test_jobs.ok(not (public.apply_generation_callback('fixture','overage-replay','fixture-job-2','failed',0,repeat('2',64))->>'applied')::boolean,'callback cannot bypass operator reconciliation');
reset role;
select test_jobs.ok((select held_cost_micros=120 and status='reconciliation_required' from private.generation_reservations where provider_job_id='fixture-job-2'),'overage reservation keeps exact known exposure');
select test_jobs.ok((select not generation_enabled from private.generation_policy),'overage disables generation');
select test_jobs.ok((select committed_micros=60 and reserved_micros=120 from private.generation_global_days),'overage callback does not duplicate settlement');
set role anon;
select test_jobs.raises($q$select public.generation_dispatch_batch(1)$q$,'42501','anon cannot read dispatch queue');
select test_jobs.raises($q$select public.apply_generation_callback('fixture','attack','fixture-job-2','failed',0,repeat('3',64))$q$,'42501','anon cannot invoke callbacks');
reset role;
set role authenticated;
select set_config('request.jwt.claims','{"role":"service_role","sub":"11000000-0000-4000-8000-000000000001"}',true);
select test_jobs.raises($q$select public.generation_job_context('00000000-0000-0000-0000-000000000000')$q$,'42501','forged service metadata does not grant context');
select test_jobs.raises($q$select public.generation_dispatch_sent('00000000-0000-0000-0000-000000000000')$q$,'42501','authenticated user cannot ack outbox');
select test_jobs.raises($q$select public.apply_generation_callback('fixture','attack','fixture-job-2','failed',0,repeat('3',64))$q$,'42501','authenticated user cannot settle callbacks');
select test_jobs.raises($q$insert into private.provider_callback_events(provider,event_id,request_id,payload_hash,outcome,applied) values('fixture','attack','00000000-0000-0000-0000-000000000000',repeat('3',64),'running',false)$q$,'42501','authenticated user cannot insert inbox');
reset role;
set role service_role;
select test_jobs.raises($q$update private.provider_job_bindings set request_id='00000000-0000-0000-0000-000000000000'$q$,'42501','service role has no raw binding write grant');
select test_jobs.raises($q$delete from private.provider_callback_events$q$,'42501','service role cannot erase replay evidence');
reset role;
select count(*)::integer as passed from test_jobs.assertions;
rollback;
